import axios from 'axios';
import '../ajax-csrf';
import { docReady } from '../lib/util';
window.docReady = docReady;
docReady(() => {
    const oweeForm = document.querySelector('#owee-form');
    if (oweeForm) {
        const errorContainer = document.querySelector('#melding');
        const submitButton = oweeForm.submitButton;
        const formulierVelden = document.querySelector('#formulierVelden');
        oweeForm.addEventListener('submit', (event) => {
            event.preventDefault();
            errorContainer.innerHTML = '';
            submitButton[0].disabled = true;
            submitButton[1].disabled = true;
            // submitButton[2].disabled = true;
            const formData = new FormData(oweeForm);
            axios
                .post('/contactformulier/owee', formData)
                .then((response) => {
                oweeForm.reset();
                submitButton[0].disabled = false;
                submitButton[1].disabled = false;
                // submitButton[2].disabled = false;
                errorContainer.innerHTML =
                    '<div class="alert alert-success">' +
                        '<i class="fas fa-check" aria-hidden="true"></i>' +
                        response.data +
                        '</div>';
                formulierVelden.style.display = 'none';
            })
                .catch((error) => {
                submitButton[0].disabled = false;
                submitButton[1].disabled = false;
                // submitButton[2].disabled = false;
                errorContainer.innerHTML =
                    '<div class="alert alert-danger">' +
                        '<i class="fas fa-ban" aria-hidden="true"></i>' +
                        error.response.data +
                        '</div>';
            });
            return false;
        });
    }
});
